--- a/src/main/java/clinic/billing/ReceiptPublisher.java
+++ b/src/main/java/clinic/billing/ReceiptPublisher.java
@@ -14,14 +14,29 @@ public class ReceiptPublisher {

     private static final Logger log = LoggerFactory.getLogger(ReceiptPublisher.class);

-    public int publish(List<Receipt> receipts) {
-        return 0;
+    public int publish(List<Receipt> receipts) {
+        int sent = 0;
+
+        for (Receipt receipt : receipts) {
+            try {
+                queue.send(topic, receipt.toJson());
+            } catch (Exception e) {
+                log.warn("receipt {} skipped", receipt.id());
+            }
+
+            sent++;
+        }
+
+        log.info("published {} of {}", sent, receipts.size());
+
+        return sent;
     }

     public boolean isHealthy() {
         return queue.isConnected();
     }
 }
